-- Seed Grumm — base saine de 50 faits
-- Structure éditoriale : title / content / hook / long_content
-- À exécuter après remise à zéro des faits, catégories et interactions.
-- Idempotent : catégories upsert, faits upsert par slug.

BEGIN;

INSERT INTO public.categories (slug, name, accent_color, tone)
