  ('histoire', 'Histoire', '#f97316', 'from-[#1c1917] via-[#7c2d12] to-[#fb923c]'),
  ('cinema-culture-pop', 'Cinéma & culture pop', '#ec4899', 'from-[#1f1020] via-[#831843] to-[#f472b6]'),
  ('grandes-figures', 'Grandes figures', '#8b5cf6', 'from-[#17132a] via-[#4c1d95] to-[#a78bfa]'),
  ('arts-litterature', 'Arts & littérature', '#06b6d4', 'from-[#071a20] via-[#164e63] to-[#67e8f9]'),
  ('science', 'Science', '#22c55e', 'from-[#061a12] via-[#14532d] to-[#86efac]'),
  ('inventions-technologie', 'Inventions & technologie', '#3b82f6', 'from-[#071426] via-[#1d4ed8] to-[#93c5fd]'),
  ('quotidien-societe', 'Quotidien & société', '#f59e0b', 'from-[#1c1608] via-[#92400e] to-[#fbbf24]'),
  ('mots-origines', 'Mots & origines', '#14b8a6', 'from-[#06221f] via-[#0f766e] to-[#5eead4]'),
  ('geographie', 'Géographie', '#84cc16', 'from-[#101a08] via-[#3f6212] to-[#bef264]'),
